package com.hrflow.platform.security;
import com.hrflow.platform.user.*; import jakarta.servlet.*; import jakarta.servlet.http.*; import lombok.RequiredArgsConstructor; import org.springframework.security.authentication.*; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter; import java.io.IOException; import java.util.List;
@Component @RequiredArgsConstructor
public class JwtAuthenticationFilter extends OncePerRequestFilter { private final JwtService jwt; private final UserRepository users;
 protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException {String h=req.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer ")&&SecurityContextHolder.getContext().getAuthentication()==null){String token=h.substring(7);try{String email=jwt.subject(token);users.findByEmailIgnoreCase(email).filter(User::isEnabled).filter(User::isEmailVerified).filter(u->jwt.valid(token,u.getEmail())).ifPresent(u->SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(u.getEmail(),null,List.of(new SimpleGrantedAuthority("ROLE_"+u.getRole().name())))));}catch(Exception ignored){}}chain.doFilter(req,res);}
}
